(4851957, 702970, 77196, '<td valign="top">Cute. Nice exposure and good DOF - the OOF foreground is not distracting, at least partly because of your strong main subject against a relatively uniform color background.</td>', 'Cute. Nice exposure and good DOF - the OOF foreground is not distracting, at least partly because of your strong main subject against a relatively uniform color background.', '2008-07-30 20:25:54.000000', NULL, 1),
(4851958, 704341, 77196, '<td valign="top">Love the hills - almost looks like the Pacific Northwest (west of the Cascades).</td>', 'Love the hills - almost looks like the Pacific Northwest (west of the Cascades).', '2008-07-30 20:27:10.000000', NULL, 1),
(4851967, 703833, 77196, '<td valign="top">I like this much better than the front view. First, it hides the dying patches of grass better. Having part of the house hidden behind the tree lends an air of mystery and suspense. Your juxtaposition of the red bush in the bottom left with the tree in the upper right gives a nice balance to the shot. The subtle color in the house itself is well done. Makes me want to pop over for a spot of tea!</td>', 'I like this much better than the front view. First, it hides the dying patches of grass better. Having part of the house hidden behind the tree lends an air of mystery and suspense. Your juxtaposition of the red bush in the bottom left with the tree in the upper right gives a nice balance to the shot. The subtle color in the house itself is well done. Makes me want to pop over for a spot of tea!', '2008-07-30 20:31:47.000000', NULL, 1),
(4851971, 703152, 77196, '<td valign="top">You have a fence like mine. But in this shot, it is too distracting - provides a strong horizontal line that slices through the head of the dragon.</td>', 'You have a fence like mine. But in this shot, it is too distracting - provides a strong horizontal line that slices through the head of the dragon.', '2008-07-30 20:33:12.000000', NULL, 1),
(4851973, 704094, 77196, '<td valign="top">Seems overprocessed to me. The foreground green and side of the weed whacker are not believable.</td>', 'Seems overprocessed to me. The foreground green and side of the weed whacker are not believable.', '2008-07-30 20:34:09.000000', NULL, 1),
(4851977, 704433, 77196, '<td valign="top">Go Jokers. Love the title. The fore ball looks much better.</td>', 'Go Jokers. Love the title. The fore ball looks much better.', '2008-07-30 20:35:36.000000', NULL, 1),
