(4859638, 703189, 47470, '<td valign="top">I wonder if this would have worked better in color.</td>', 'I wonder if this would have worked better in color.', '2008-08-02 15:54:22.000000', NULL, 1),
(4859704, 704256, 66819, '<td valign="top">Not much lawn in this picture.</td>', 'Not much lawn in this picture.', '2008-08-02 16:31:15.000000', NULL, 1),
(4859708, 704387, 66819, '<td valign="top">Very good shot. The shadows are a little strong, but this picture overall gives the feel of a Monet painting. The subject matter seems unfocused as there is nothing really that draws the eye to focus on in the picture.</td>', 'Very good shot. The shadows are a little strong, but this picture overall gives the feel of a Monet painting. The subject matter seems unfocused as there is nothing really that draws the eye to focus on in the picture.', '2008-08-02 16:33:28.000000', NULL, 1),
(4859711, 704221, 66819, '<td valign="top">this picture is too saturated with green.</td>', 'this picture is too saturated with green.', '2008-08-02 16:34:49.000000', NULL, 1),
(4859715, 702948, 66819, '<td valign="top">Captures a wide range of colors, making this a very good picture. it has focus points, although the lawn doesn''t exactly figure prominently into the picture, which detracts from the spirit of the competition.</td>', 'Captures a wide range of colors, making this a very good picture. it has focus points, although the lawn doesn''t exactly figure prominently into the picture, which detracts from the spirit of the competition.', '2008-08-02 16:36:55.000000', NULL, 1),
(4859718, 703875, 66819, '<td valign="top">A very symmetrical picture! The blue sky and slightly dried out lawn give a summery, but relaxed feel.</td>', 'A very symmetrical picture! The blue sky and slightly dried out lawn give a summery, but relaxed feel.', '2008-08-02 16:38:27.000000', NULL, 1),
(4859721, 703888, 66819, '<td valign="top">A good abstract photo of blades of grass is exactly the kind of photo this competition begs for. it features grass (obviously) and thus speaks to the theme of the competition. The picture has no real one point to focus on, although the right side tends to draw the eye toward it. the overall feel of the picture is very good.</td>', 'A good abstract photo of blades of grass is exactly the kind of photo this competition begs for. it features grass (obviously) and thus speaks to the theme of the competition. The picture has no real one point to focus on, although the right side tends to draw the eye toward it. the overall feel of the picture is very good.', '2008-08-02 16:42:34.000000', NULL, 1),
(4859909, 702534, 96815, '<td valign="top">something strangely creepy about this. good picture however.</td>', 'something strangely creepy about this. good picture however.', '2008-08-02 18:01:22.000000', NULL, 1),
(4859927, 703795, 96815, '<td valign="top">incredible photo</td>', 'incredible photo', '2008-08-02 18:26:10.000000', NULL, 1),
(4860068, 703495, 31535, '<td valign="top">First thing I notice it it looks small which is never good. Always make use of the 640px size limit.<br/> <br/>That being said, this is a really nice abstract shot, with good tones and exposure. Nice take on the challenge.</td>', 'First thing I notice it it looks small which is never good. Always make use of the 640px size limit. That being said, this is a really nice abstract shot, with good tones and exposure. Nice take on the challenge.', '2008-08-02 20:57:36.000000', NULL, 1),
(4860334, 702590, 89669, '<td valign="top">I love the DOF! Great Job</td>', 'I love the DOF! Great Job', '2008-08-02 23:47:34.000000', NULL, 1),
(4860676, 703616, 69368, '<td valign="top">can''t guess what this is ?</td>', 'can''t guess what this is ?', '2008-08-03 04:59:15.000000', NULL, 1),
